WoWFQ[86838] = { t = "نوزایی برای خستگان", d = "Vanguard of the Light مراسمی دشوار را در Sunwell نگه داشته است. تمرکز می‌خواهد، انضباط می‌خواهد و به‌شدت فرساینده است.\nعصایم را بگیر. از روزهایی که در Stormwind Archbishop بودم داردم. برای من و ایمانم معنادار است. Light به معنا و نیت پاسخ می‌دهد. باید روحیه Vanguard را نو کند تا بتوانند مراسم را کمی طولانی‌تر نگه دارند.\nنمی‌توانم خودم به Sunwell نزدیک شوم، پس این کار را برای من می‌کنی.", o = { "Light را به 10 کانال‌گر خسته بازگردان.", "Sunwell Channeler نو شد", "Sunwell Channeler را بکش", "Sunwell Channeler را بکش" }, c = "امید داشتم با دیدن تمرکز بقیه Vanguard بر Sunwell، هدفی بزرگ‌تر از رنجشش ببیند و از خشمش دور شود. اما به جایش، راه‌حل من را خوار شمرد.\nممنونم، <name>، که به جای او این کار را کردی. برای مهار Voidstorm لازم بود." }
WoWFQ[86839] = { t = "یادگارهای Light's Hope", d = "قدرت مقدس عصایم تمام شد. چهل سال دعای پرشور در چند دقیقه آب شد. برای هدف خوبی بود و عصایم به‌مرز بازمی‌گردد.\nیادگارهای دیگری هم هستند، مثل عصای من، که برای paladinها و priestها مهم بودند. Light's Hope Chapel یادگارهای زیادی از این جنس را نگه می‌دارد.\nArator هم آنجا آموزش دیده است. شاید درمان درد او هم همان‌جا پیدا شود.", o = { "در Light's Hope Chapel با Lord Maxwell Tyrosus دیدار کن.", "اندکی بمان و گوش کن", "با Alonsus Faol صحبت کن", "Arator و Faol می‌روند" }, c = "به Light's Hope خوش آمدی، <name>.\nبیشتر paladinهایی که از این زمین‌ها دفاع کردند، به دست Light فراخوانده شده بودند. ناچار شدم برای پشتیبانی سراغ Ebon Blade بروم، وگرنه Scourge این مکان مقدس را له می‌کرد." }
WoWFQ[86845] = { t = "راه Sunwalker", d = "فکر می‌کنم در حق Arator کوتاهی کرده‌ام. در تلاش برای آرام کردنش بعد از ماجرای پدرش، شاید با آن حقیقت‌های ناخوشایند درباره Light، ایمانش را خرد کرده باشم.\nدوست دارم با خردمندترین کسی که می‌شناسم مشورت کنم، Sunwalker Dezco. او را میان Vanguard ندیدم. Tyrosus گفت شاید در Hammerfall باشد و به آوارگان کمک می‌کند.", o = { "در Hammerfall با Sunwalker Dezco دیدار کن.", "به Alonsus بگو آماده حرکتی", "درگاه را باز کن", "با درگاه به Hammerfall برو", "Leave Area Trigger", "Show Trash in Hammerfall" }, p = "خوش آمدی، <name>. اگر willing باشی، کار زیادی اینجاست!", c = "An'she تو را به ما رسانده، <name>. حاضری در کارمان سهیم شوی؟" }
WoWFQ[86902] = { t = "واگذاری یادگارها", d = "عصایم در نگه داشتن Void وقت خرید، اما این یادگارها یاری نیرومندتری خواهند بود. امیدوارم کافی باشد.\nسریع، این یادگارها را به دوستانمان برسان.", o = { "یادگارها را به Taelia، Valunei، Salandria و Mehlar برسان.", "Arator و Faol می‌روند", "گفتگوی پیش‌نمایش اول", "با Aelyse صحبت کن (4)", "یادگارها پخش شد", "یادگار به Taelia رسید", "یادگار به Valunei رسید", "یادگار به Salandria رسید", "یادگار به Mehlar رسید" }, p = "یادگارها را به همه رساندی، <name>؟", c = "با این یادگارها، باید بتوانند مراسم را خیلی طولانی‌تر نگه دارند.\nو ما هم می‌توانیم سراغ کارهای دیگر برویم." }
