WoWFQ[90862] = { t = "در روزهای نیازمندی", d = "آخرین رهبران الف با قدرت‌هایی از سرزمین‌هایشان برگشته‌اند که در پاک‌سازی Darkwell به ما کمک می‌کند.\nهرچند Voidstorm دیگر بر Darkwell توپ نمی‌باراند، هنوز به شفا نیاز دارد.\nلطفا با بقیه رهبران دیدار کن و به‌شان خبر بده برایشان آماده‌ایم.", o = { "با هر یک از رهبران الف صحبت کن.", "هیئت Kaldorei دیده شد", "هیئت Shal'dorei دیده شد", "هیئت Ren'dorei دیده شد", "هیئت Quel'dorei دیده شد" }, c = "الف‌های همه ملت‌ها قرن‌هاست که از چاه‌ها برای جادو، برای زندگی و برای هویت می‌کشند. حتی اژدهایان بزرگ هم در این ساعت به دانش ما نمی‌رسند." }
WoWFQ[90867] = { t = "از تاریکی، Light", d = "نمی‌گذاریم Sunwell باز هم آلوده شود. این Darkwell باید تغییر کند، اما به چیزی بدل شود که دیگر به چنین وابستگی‌ای به آن گره نخوریم. لازم نیست این چاه طعمه نیروهای دیگر آلوده‌کننده جهان باشد.\nنه، امروز Darkwell را شفا می‌دهیم و از آن چیز تازه‌ای می‌سازیم. هر وقت آماده بودی خبرم کن.", o = { "مراسم پاک‌سازی Darkwell را برگزار کن.", "برای آغاز مراسم با Liadrin صحبت کن" }, c = "بنگر Dawnwell. انشاالله آب‌هایش هرگز آلوده نشنود. انشاالله یادگاری باشد از همه آنچه از دست داده‌ایم، و الهامی برای آنچه می‌توانیم بشویم." }
WoWFQ[92136] = { t = "تزریق امید", d = "امیدوارم نور عصایم برای پابرجا نگه داشتن آن‌ها در Sunwell، حین جست‌وجوی این یادگارها، کافی بوده باشد.\nهمراه با آنچه از Light's Hope آورده‌ایم، باید کمک بسیار پررنگ‌تری باشند.\nسریع به آنجا برگردیم.", o = { "یادگارها را به Silvermoon برگردان.", "به Alonsus بگو آماده حرکتی", "درگاه را باز کن", "با درگاه به Silvermoon برو" }, c = "سریع باش، <name>. بگذار پخش‌شان کنیم!" }
WoWFQ[94957] = { t = "جنگ Light و Shadow", d = "Vanguard نیروهایش را برای رویارویی با Devouring Host بسیج کرده است.\nدر Sunwell به Lady Liadrin گزارش بده تا به حمله بپیوندی.", o = { "در Sunwell با Liadrin صحبت کن.", "با Lady Liadrin صحبت کن" }, p = "Devouring Host کوشید ما را بشکند. به‌زودی، توان ترکیبی Vanguard را خواهند دید.", c = "خط را با خون و Light نگه داشتیم. حالا، ضربه متقابل می‌زنیم." }
WoWFQ[96226] = { t = "ناهنجاری‌های Omnium", d = "کمی بعد از بیدار شدن Omnium، شروع به مجسم کردن ناهنجاری‌های arcane در اطراف Lycaneum کرد.\nبه باور ما این ناهنجاری‌ها پروتکل‌های امنیتی خراب‌اند--تجلی‌های خصمانه‌ای که احضار می‌کنند می‌توانند کشنده باشند.\nاگر سریع از پایشان درنیاییم، به مجسم شدن ادامه می‌دهند.\nحین رسیدگی به آن‌ها، مواظب هر چیز عجیبی باش که به فهم وضعیت فعلی Omnium کمک کند.", o = { "با ناهنجاری‌های Arcane در اطراف Lycaneum روبه‌رو شو.", "Omnial Anomalyها روبه‌رو شدند (3)", "Image of Dar'Khan Drathir را بکش", "Image of Dath'Remar Sunstrider را بکش", "Image of Kael'thas Sunstrider را بکش" }, p = "این ناهنجاری‌های arcane همه‌جای Terrace ظاهر می‌شوند، اما خدا را شکر بیشترشان را مهار کرده‌ایم.\nحواست باشد، <name>. آن‌ها که در Lycaneum هستند به نظر بی‌ثبات‌ترین‌اند.", c = "ناهنجاری‌ها تصویر Dar'Khan را مجسم کردند؟ مطمئنی؟\nمی‌دانستیم آن خائن به Magisters' Terrace آمد تا convocation را قصاب کند و بعد Sunwell را خلع سلاح کند.\nهیچ نشانه‌ای نبود که به Omnium آسیب زده باشد. نه خطی، نه زخمی رویش.\nشاید آسیب Dar'Khan پیش از سقوط Anasterian رخ داده و به سکوت ناگهانی Omnium انجامیده..." }
WoWFQ[96227] = { t = "آشوب Lycaneum", d = "وقتی Omnium در گنجینه‌اش جنبید، تصمیم گرفتیم برای مشاهده به اینجا بیاوریم. evidently یعنی به گواهی ماجرا، ایده بدی بود.\nجادوهای arcane که از آن می‌چکند، آشوب به پا کرده است.\nFolioها هر طلسم ناتمامی را شلیک می‌کنند، جرقه‌های arcane سر به شورش گذاشته‌اند--حتی شعله‌های شمع جان گرفته‌اند!\nاما نمی‌شود ساده از پایشان درآمد، چون جادوهای اینجا بیش از حد بی‌ثبات‌اند. یک ward-lance از زرادخانه spellbreakerها تهیه کرده‌ام. جادوی بی‌ثبات را می‌زداید.\nبگیر، این را. و حتما مراقب باش.", o = { "آشوب برخاسته از arcane را در Lycaneum فرو نشان.", "آشوب کتابخانه پاک شد", "Arcane Sparkling را بکش (25)", "Book را بکش (13)", "[DNT] Kill Credit: Candle Light Cleansed را بکش (17)" }, p = "اگر یکی دیگر از آن Folioها تو صورتم منفجر شود، شاید همه کتاب‌های پرنده این مکان را به آتش بکشم.", c = "<Rommath exhales a sigh of relief.>\nاین آشوب شاید مسخره به نظر برسد و طلسم‌هایش بی‌ضرر، اما مطمئن باش اگر مهارش نمی‌کردیم به کتابخانه، کل ساختمان به آشوبی علمی می‌افتاد.\nبه احترام همه Magisterهای اینجا، از تو ممنونم." }
WoWFQ[96230] = { t = "گشودن طلسم‌ها", d = "Magiculeها، گوی‌هایی که روی یادگار می‌بینی، هرگز نباید از Omnium جدا می‌شدند. با کندن یکی، Dar'Khan احتمالا یادگار را پیش از خاموشی به حالتی دیوانه‌وار انداخت.\nحتی اگر Void Magicule برگردد، Omnium به کالیبره شدن نیاز دارد. برای این کار به key-cipher ی Belo'vir نیاز داریم؛ که حالا key-cipher من است.\nدر اتاق کارم به من می‌پیوندی و آن را پس می‌گیریم.", o = { "در جزیره Quel'Danas در اتاق کارش به Grand Magister Rommath بپیوند.", "نزدیک شو", "در Grand Magister's Office با Rommath صحبت کن", "طلسم اول گشوده شد", "طلسم دوم گشوده شد", "طلسم سوم گشوده شد", "[DNT] Top Platform را بکش" }, p = "بگذار Belo'vir Salonar یک بار دیگر فخر فروشی‌اش بر arcane را به رخ بکشد...", c = "تسلط Belo'vir Salonar بر طلسم تصویر آینه‌ای برای خیلی‌ها شناخته‌شده بود. رساله arcane‌اش درباره «سه‌گانه‌سازی آینه‌ای» نخستین سهمش را در Arcane Magicule ی Omnium رقم زد.\nهمان هم طلسم محبوبش برای سرکیسه کردن شاگردهایش بود. بی‌اختیار فکر می‌کنم آیا می‌دانست از این آخرین شوخی چقدر خوشم نمی‌آید.\nبه هر روی، شاهکار بود. یک طلسم دیگر مانده." }
WoWFQ[96231] = { t = "Key-Cipher ی Grand Magister", d = "بعد از مرگ Belo'vir، در باز کردن این گنجینه اندیشه کردم. خودم را منصرف کردم.\nکلیدی برای قفلی شکسته، به چه کار می‌آید؟\nو با این حال، حتی وقتی Kael'thas با کلیدش می‌خواست بازش کند، بی‌اختیار فکر می‌کردم...\nبی‌مهم است، <name>. تقریبا کار طلسم بزرگ طبقه بالا تمام است. همان‌جا به من بپیوند.\nبی‌گمان Belo'vir برای محافظت از گنجینه‌اش گام‌های اضافی برداشته است.", o = { "به Grand Magister Rommath در گشودن آخرین محافظ Belo'vir کمک کن.", "به طبقه بالا نزد Rommath برو", "گنجینه Arcane را باز کن", "Grand Magister's Key-Cipher را بردار" }, p = "بعد از این همه ماجرا...", c = "وقتی شاگرد بودم، Belo'vir درباره key-cipherهای Omnium سخنرانی کرد.\nبرای محافظت از کلیدها، هر cipher شکلی می‌گرفت که فقط مالکش می‌شناخت.\nKael'thas کلیدش را داشت؛ که حالا گم شده. و Belo'vir مال خودش را... در گنجینه‌اش مهر و موم کرده بود.\nکنجکاوم Kael'thas چه شکلی برایش برگزیده بود.\n<Rommath حرفش نیمه‌کاره می‌ماند و به کلید در کف دستش خیره می‌شود؛ تصویر جابه‌جاشونده‌اش رمزگشایی را ناممکن می‌کند.>" }
WoWFQ[96233] = { t = "بیداری دوباره Omnium", d = "سال‌ها، حین اینکه Silvermoon و مردمش دگرگون می‌شدند، این یادگار در گنجینه‌ای زیر Terrace بی‌پاسخ و خفته ماند.\nشاید هرگز نفهمیم چرا یادگار در آن لحظه خاموش شد یا چرا ندای شاهزاده را نپذیرفت، اما شاید به‌مرز بفهمیم.\nامیدوارم Magicule گمشده و key-cipher برای بازگرداندنش کافی باشند.\nآماده‌ای، <name>؟", o = { "برای آغاز با Grand Magister Rommath صحبت کن.", "Sunstrider Omnium فعال شد" }, c = "بیشتر Magisterها--خود من هم--امید بازگشتش را رها کرده بودند.\nیورش Void به Sunwell بود که بیدارش کرد؟ یا Dawnwell؟ شاید هرگز نفهمیم.\nآنچه می‌دانم این است که به لطف تو در حضورش ایستاده‌ایم، <name>.\nمعمولا با پاداشی خوش‌قیمت بدرقه‌ات می‌کردم، اما شاید چیزهای بیشتری باشد که بتوانی یاری‌مان کنی.\nالبته، با پاداشی حتی بزرگ‌تر..." }
WoWFQ[96238] = { t = "بازگشت به Omnium", d = "با بازیابی key-cipher ی Belo'vir و دست داشتن Umbric بر Void Magicule، باید به Lycaneum بازگردیم.\nامیدوارم هر آنچه برای کالیبره کردن Sunstrider Omnium لازم است را داشته باشیم.\nوقتی کارم اینجا تمام شد در Magisters' Terrace به تو می‌پیوندم.", o = { "به Sunstrider Omnium در Magisters' Terrace بازگرد.", "با درگاه به Magisters' Terrace برو", "به Omnium بازگرد" }, p = "بدون شبکه گمشده و key-cipher، هیچ راهی برای متوقف کردن خرابی‌های Omnium نداریم.", c = "وقتی بار Grand Magister بودن را برداشتم، در آن روزگار آشوب، حساب‌کتاب‌های زیادی ماند.\nKey-Cipher ای که به من رسید آن وقت بی‌اهمیت به نظر می‌رسید، به‌خصوص وقتی کلید خود شاهزاده هم کار نمی‌کرد.\nدعا می‌کنم هر چیزی که روزی با Sunstrider Key-Cipher کاری کرد، امروز سر راهمان سبز نشود.\nفقط یک کار باقی مانده." }
WoWFQ[96410] = { t = "طلب دانش، هفته 1 از 5: Folio ی Omnium", d = "کسانی که می‌خواستند از Omnium بیاموزند باید به آن سهمی می‌دادند.\nدر حالی که بیشتر Magisterها درون Terrace درس می‌خواندند، عده‌ای برگزیده به عنوان «طالبان خرد» برگزیده می‌شدند.\nطالبان جادوهای تازه و بیگانه را می‌جستند تا به فهرست عظیم Omnium برای مطالعه بیفزایند.\nبا توجه به تجربه... ماجراجویانه تو، به نظرم seeker عالی می‌شوی.\nاگر علاقه داری، Grand Magister بیشتر توضیح می‌دهد.", o = { "Omnium Folio خودت را از Grand Magister Rommath بگیر و نخستین رُن‌ات را نیرومند کن.", "با Grand Magister Rommath صحبت کن", "Omnium Folio دریافت شد", "Omnium Folio خودت را باز کن و نخستین رُن‌ات را نیرومند کن" }, p = "چه تئوری‌های جادویی، چه رُن‌کارهای پیچیده، چه نمونه‌های برداشت‌شده از جادو--Omnium برای نگهداری دانش ساخته شده بود تا Magisterهای آینده بیاموزند، به کار گیرند و بر کار پیشینیان مسلط شوند.", c = "هرچند انتظار نداریم بر رازهای اصلی Void یا آتش مسلط شوی، چند رُن سودمند برگزیده‌ایم تا در نبرد یاری‌ات کند.\nبا هر تکلیف پژوهشی هفتگی که بدهی، من و Umbric سری تازه از رُن‌ها را برای Omnium Folio ات انتخاب می‌کنیم.\nفعلا رُن تازه‌ات را آزمایش کن تا من و Umbric تکلیف بعدی‌ات را آماده کنیم." }
WoWFQ[96443] = { t = "طلب دانش، هفته 4 از 5: Primessence جادویی", d = "به لطف تلاش‌های تو، اثر مقادیر ناچیز جادوی بیگانه را که با ley lineها هم‌جور می‌شود، جدا کرده‌ایم.\nفصل بعدی کار، مقایسه این نتایج با نمونه خالصی از جادو است که با همان انرژی هم‌جور می‌شود.\nکار تو ردیابی یک primessence از جادوست--چه arcane چه Void چه Light چه دیگر--و گرفتنش از سرچشمه مرگبارش.\nموفق باشی، <name>.", o = { "1 Primessence of Magic از ارباب نهایی هر دانژان یا دلوه، از Illustrious Contender's Strongbox یا از رaid ی Sporefall جمع کن.", "یک Pure Magical Primessence بازیابی کن", "Primessence of Shadow", "Primessence of Death", "Primessence of Arcane", "Primessence of Life", "Primessence of Light", "Primessence of Fel" }, p = "اگر بتوانیم اثر مقادیر ناچیز جادو و سرچشمه‌های قوی‌تر جادو را حین هم‌جور شدن با انرژی‌های ley در Quel'Thalas اندازه بگیریم، شاید بتوانیم پیش‌بینی کنیم برای Dawnwell چه معنایی دارد.\nو به‌خاطر ویژگی‌های یکتای Dawnwell، هر سرچشمه اصلی جادو کافی است--البته برای آزمایش‌های ما.", c = "<چشمان Umbric گرد می‌شود حین گرفتن با دقت primessence از دست تو.>\nیافته‌ای حیرت‌انگیز، <name>.\nهرچند سرچشمه‌ای این‌قدر نیرومند مستقیم در Dawnwell تزریق نشده بود، برای آزمایش‌های ایزوله‌مان بیش از حد کافی است.\nدوست داشتم تماشا کنی، اما می‌ترسم پیش از هر چیز هیجان‌انگیز، کلی نظریه‌پردازی و نوشتن فرمول در کار باشد.\nبه رُن‌های تازه‌ای که برایت برگزیده‌ایم نگاهی بینداز. به گمانم از انتخاب این هفته خوشت بیاید." }
